// People visual baselines (#849, #82 part 3): every viewport × theme project (360/768/1280, light
// and dark): the list, the new contact dialog, the detail page (linked and unlinked), the Tamil and
// Kannada rows, and the empty and error states. The seeded contacts are fixed, so nothing needs a
// frozen clock. Baselines live in e2e/__screenshots__ and are only ever generated by the e2e
// workflow's `update_snapshots` dispatch in the pinned Playwright image (see e2e/README.md);
// without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Locator, Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import { MATTERS_WORKSPACE } from '../../fixtures/matters-data.ts';
import { expect, test } from '../../fixtures/index.ts';

import {
  CONTACTS,
  emptyContacts,
  openPeople,
  peoplePath,
  seedContacts,
  volatile,
} from './helpers.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

interface Shot {
  name: string;
  /** `database` is the worker database. Returns the element to shoot, or the page. */
  setUp: (page: Page, asUser: AsUser, database: string) => Promise<Locator | null>;
}

const open =
  (path: string, ready: (page: Page) => Locator): Shot['setUp'] =>
  async (page, asUser, database) => {
    await seedContacts(database);
    await openPeople(page, asUser, { path });
    await expect(ready(page).first()).toBeVisible();
    return null;
  };

const rows = (page: Page) => page.locator('a[data-contact-row]');

const SHOTS: readonly Shot[] = [
  { name: 'people-list.png', setUp: open(peoplePath(), rows) },
  {
    name: 'people-list-tamil-kannada.png',
    setUp: open(peoplePath(undefined, 'language=ta'), (page) =>
      page.locator(`a[data-contact-row="${CONTACTS.tamil.id}"]`),
    ),
  },
  {
    name: 'people-new-contact.png',
    setUp: async (page, asUser, database) => {
      await seedContacts(database);
      await openPeople(page, asUser);
      await page.locator('[data-slot="new-contact"]').first().click();
      const dialog = page.getByRole('dialog');
      await expect(dialog).toBeVisible();
      return dialog;
    },
  },
  {
    name: 'people-detail-linked.png',
    setUp: open(peoplePath(CONTACTS.linked.id), (page) =>
      page.locator('[data-linked-matters="list"]'),
    ),
  },
  {
    name: 'people-detail-unlinked.png',
    setUp: open(peoplePath(CONTACTS.unlinked.id), (page) =>
      page.locator('[data-linked-matters="empty"]'),
    ),
  },
  {
    name: 'people-empty.png',
    setUp: async (page, asUser, database) => {
      await emptyContacts(database);
      await openPeople(page, asUser);
      await expect(page.locator('main [data-pattern-state="empty"]')).toBeVisible();
      return null;
    },
  },
  {
    name: 'people-error.png',
    setUp: async (page, asUser, database) => {
      await seedContacts(database);
      await openPeople(page, asUser);
      await page.goto(`/w/${MATTERS_WORKSPACE}/people?__state=error`);
      await expect(page.locator('main [data-pattern-state="error"]')).toBeVisible({
        timeout: 15_000,
      });
      return null;
    },
  },
];

test.describe('people visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser, db }, testInfo) => {
        skipWithoutBaseline(testInfo, shot.name);
        const target = await shot.setUp(page, asUser, db.name);
        const options = { animations: 'disabled', caret: 'hide', mask: volatile(page) } as const;
        if (target === null) await expect(page).toHaveScreenshot(shot.name, options);
        else await expect(target).toHaveScreenshot(shot.name, options);
      },
    );
  }
});
